head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플 실행 후 input1,input2, input3의 inputbox각각에 '가나다123abc'값을 입력한다.
    //1. After executing the sample, enter the value '가나다123abc' in each input box of input1, input2, input3.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').setValue('가나다123abc')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input2').setValue('가나다123abc')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input3').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input3').setValue('가나다123abc')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input3').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1-1. inputbox1에는 '123abc' 값이 입력된다.
    // 1-1. inputbox1 is entered with the value '123abc'.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getValue() == '123abc'", "true");
    //Verify 1-2. inputbox2에는 '123' 값이 입력된다.
    //1-2. '123' is entered in inputbox2.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input2').getValue() == '123'", "true");
    //Verify 1-3. inputbox3에는 '가나다123' 값이 입력된다.
    //1-3. inputbox3 is entered with the value '123'.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input3').getValue() == '가나다123'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 23-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
